style.css:
@-moz-document domain("twitter.com"), domain("x.com") {
:root {
        --fundo-principal: #E3EDFC; /* Cor exata da imagem_2.png */
        --fundo-cartoes: #FFFFFF;
        --texto-principal: #3B5266;
        --bordas-claras: #C4DCFA;
        --sombra-fofa: rgba(196, 220, 250, 0.4);
        --destaque-ativo: #A5CDFA;
        --icone-destaque: #4B92E6;
        --fundo-hover: #D4E5FA;
        --fundo-busca: #D4E5FA;
    }

    body {
        background-color: var(--fundo-principal) !important;
        color: var(--texto-principal) !important;
    }

    div, article, header, nav {
        border-color: var(--bordas-claras) !important;
    }

    [data-testid="tweet"], 
    [data-testid="placementTracking"] article,
    [data-testid="sidebarColumn"] > div > div > div > div {
        background-color: var(--fundo-cartoes) !important;
        border-radius: 20px !important;
        margin-bottom: 10px !important;
        box-shadow: 0 4px 10px var(--sombra-fofa) !important;
    }

    a[href="/compose/post"], 
    [data-testid="SideNav_NewTweet_Button"],
    div[role="progressbar"] {
        background-color: var(--destaque-ativo) !important;
    }
    
    a[href="/compose/post"] span, 
    [data-testid="SideNav_NewTweet_Button"] span {
        color: #FFFFFF !important;
    }

    nav a svg, 
    nav div[role="button"] svg,
    a {
        color: var(--icone-destaque) !important;
    }

    [data-testid="SideNav_AccountMenu_Button"],
    nav a {
        border-radius: 15px !important;
    }
    nav a:hover {
        background-color: var(--fundo-hover) !important;
    }

    [data-testid="SearchBox_Search_Input_Container"] {
        background-color: var(--fundo-busca) !important;
        border-radius: 25px !important;
    }
    
    main {
        background-color: var(--fundo-principal) !important;
    }
    
    span, time, div {
        font-family: "Segoe UI", Roboto, Helvetica, Arial, sans-serif !important;
    }
}
